    static void renderCombinedWaveItems(
            JPanel targetPanel,
            Map<Integer, Map<String, ItemAggregate>> historicalByWave,
            MokhaDisplaySortMode sortMode,
            boolean displayHaValueOnHover,
            boolean usePricePerItemForUniqueColor,
            Color totalTextColor,
            boolean enableHistoricalEdit,
            HistoricalInteractionBinder historicalInteractionBinder,
            Map<String, String> uniqueWaveTooltips) {
        targetPanel.removeAll();

        HistoricalAggregateCombiner.CombinedAggregateResult combinedResult = HistoricalAggregateCombiner
                .combine(historicalByWave);
        long totalValue = combinedResult.getTotalValue();
        long totalHaValue = combinedResult.getTotalHaValue();

        for (ItemAggregate aggregate : LootPanelDisplayUtils
                .sortAggregatesForDisplay(combinedResult.getCombined().values(), sortMode)) {
            JPanel itemRow = new JPanel(new BorderLayout());
            itemRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
            itemRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
            itemRow.setBorder(new EmptyBorder(2, 5, 2, 0));

            JLabel itemLabel = new JLabel("- " + aggregate.name + " x" + aggregate.totalQuantity);
            Color itemColor = isUltraValuable(aggregate, usePricePerItemForUniqueColor)
                    ? new Color(218, 165, 32)
                    : ColorScheme.LIGHT_GRAY_COLOR;
            itemLabel.setForeground(itemColor);
            itemLabel.setFont(FontManager.getRunescapeSmallFont());

            String pricePerItemText = LootPanelDisplayUtils.formatPricePerItemTooltip(
                    aggregate.pricePerItem,
                    aggregate.haPricePerItem,
                    displayHaValueOnHover);
            String waveTooltip = uniqueWaveTooltips != null ? uniqueWaveTooltips.get(aggregate.name) : null;
            String tooltip = waveTooltip != null
                    ? waveTooltip + " | Price per item: " + pricePerItemText
                    : "Price per item: " + pricePerItemText;
            itemRow.setToolTipText(tooltip);
            itemRow.add(itemLabel, BorderLayout.WEST);

            JLabel itemValueLabel = new JLabel(LootPanelDisplayUtils.formatGp(aggregate.totalValue));
            itemValueLabel.setForeground(itemColor);
            itemValueLabel.setFont(FontManager.getRunescapeSmallFont());
            itemValueLabel.setToolTipText(
                    LootPanelDisplayUtils.formatGeHaTotalText(aggregate.totalValue, aggregate.totalHaValue));
            itemRow.add(itemValueLabel, BorderLayout.EAST);

            if (enableHistoricalEdit && historicalInteractionBinder != null) {
                historicalInteractionBinder.bind(itemRow, aggregate.name);
            }

            targetPanel.add(itemRow);
        }

        targetPanel.add(Box.createVerticalStrut(8));

        if (!displayHaValueOnHover) {
            JLabel totalLabel = new JLabel("Total: " + LootPanelDisplayUtils.formatGp(totalValue));
            totalLabel.setFont(FontManager.getRunescapeBoldFont());
            totalLabel.setForeground(totalTextColor);
            targetPanel.add(totalLabel);
        } else {
            JPanel totalRow = new JPanel(new BorderLayout());
            totalRow.setBackground(ColorScheme.DARK_GRAY_COLOR);
            totalRow.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));

            JLabel totalText = new JLabel("Total:");
            totalText.setFont(FontManager.getRunescapeFont());
            totalText.setForeground(Color.LIGHT_GRAY);
            totalRow.add(totalText, BorderLayout.WEST);

            JPanel valuesPanel = new JPanel();
            valuesPanel.setBackground(ColorScheme.DARK_GRAY_COLOR);
            valuesPanel.setLayout(new BoxLayout(valuesPanel, BoxLayout.X_AXIS));

            JLabel geTotalLabel = new JLabel("GE: " + LootPanelDisplayUtils.formatGp(totalValue));
            geTotalLabel.setFont(FontManager.getRunescapeFont());
            geTotalLabel.setForeground(Color.WHITE);

            JLabel haTotalLabel = new JLabel(" | HA: " + LootPanelDisplayUtils.formatGp(totalHaValue));
            haTotalLabel.setFont(FontManager.getRunescapeFont());
            haTotalLabel.setForeground(new Color(0, 200, 0));

            valuesPanel.add(geTotalLabel);
            valuesPanel.add(haTotalLabel);
            totalRow.add(valuesPanel, BorderLayout.EAST);
            targetPanel.add(totalRow);
        }

        targetPanel.revalidate();
        targetPanel.repaint();
    }

    private static boolean isUltraValuable(ItemAggregate aggregate,
            boolean usePricePerItemForUniqueColor) {
        if (LootPanelDisplayUtils.UNIQUE_ITEM_NAMES.stream().anyMatch(n -> n.equalsIgnoreCase(aggregate.name))) {
            return true;
        }
        long value = usePricePerItemForUniqueColor ? aggregate.pricePerItem : aggregate.totalValue;
        return value > 20_000_000;
    }
}

package com.camjewell;

import java.awt.Color;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;

final class LootPanelDisplayUtils {
    static final Set<String> UNIQUE_ITEM_NAMES = Set.of(
            "Dom", "Avernic treads", "Eye of ayak (uncharged)", "Mokhaiotl cloth");

    private LootPanelDisplayUtils() {
    }

    static List<ItemData> sortItemDataForDisplay(
            java.util.Collection<ItemData> items,
            MokhaDisplaySortMode sortMode) {
        List<ItemData> sorted = new ArrayList<>(items);
        if (sortMode == MokhaDisplaySortMode.VALUE_DESC) {
            sorted.sort(Comparator
                    .comparingLong((ItemData item) -> item.totalValue).reversed()
                    .thenComparing(item -> item.name, String.CASE_INSENSITIVE_ORDER));
        } else {
            sorted.sort(Comparator.comparing(item -> item.name, String.CASE_INSENSITIVE_ORDER));
        }
        return sorted;
    }

    static List<ItemAggregate> sortAggregatesForDisplay(
            java.util.Collection<ItemAggregate> items,
            MokhaDisplaySortMode sortMode) {
        List<ItemAggregate> sorted = new ArrayList<>(items);
        if (sortMode == MokhaDisplaySortMode.VALUE_DESC) {
            sorted.sort(Comparator
                    .comparingLong((ItemAggregate item) -> item.totalValue).reversed()
                    .thenComparing(item -> item.name, String.CASE_INSENSITIVE_ORDER));
        } else {
            sorted.sort(Comparator.comparing(item -> item.name, String.CASE_INSENSITIVE_ORDER));
        }
        return sorted;
    }

    static String formatGp(long value) {
        if (value >= 1_000_000_000 || value <= -1_000_000_000) {
            return String.format("%.3fB gp", value / 1_000_000_000.0);
        } else if (value >= 1_000_000 || value <= -1_000_000) {
            return String.format("%.2fM gp", value / 1_000_000.0);
        } else if (value >= 1_000 || value <= -1_000) {
            return String.format("%.1fK gp", value / 1_000.0);
        } else {
            return value + " gp";
        }
    }

    static String formatTotalWithOptionalHa(long geTotal, long haTotal, boolean displayHaValueOnHover) {
        if (!displayHaValueOnHover) {
            return formatGp(geTotal);
        }

        return String.format(
                "<html><span style='color:%s'>GE: %s</span> <span style='color:%s'>| HA: %s</span></html>",
                colorToHex(Color.WHITE),
                formatGp(geTotal),
                colorToHex(new Color(0, 200, 0)),
                formatGp(haTotal));
    }

    static String formatGeHaTotalText(long geTotal, long haTotal) {
        return formatGeHaTotalText(formatGp(geTotal), formatGp(haTotal));
    }

    static String formatGeHaTotalText(String geText, String haText) {
        return String.format("GE: %s | HA: %s", geText, haText);
    }

    static String formatPricePerItemTooltip(long pricePerItem, long haPricePerItem, boolean includeHa) {
        if (pricePerItem < 0 && haPricePerItem < 0) {
            return "N/A";
        }

        if (!includeHa) {
            return formatGp(pricePerItem) + "/ea";
        }

        return String.format("%s/ea, HA: %s/ea", formatGp(pricePerItem), formatGp(haPricePerItem));
    }

    static boolean isUniqueLootItem(ItemData item) {
        if (item == null) {
            return false;
        }

        return UNIQUE_ITEM_NAMES.stream().anyMatch(n -> n.equalsIgnoreCase(item.name));
    }

    private static String colorToHex(Color color) {
        return String.format("#%02x%02x%02x", color.getRed(), color.getGreen(), color.getBlue());
    }
}

package com.camjewell;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

import org.slf4j.Logger;

import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.Notifier;
import net.runelite.client.game.ItemManager;

class LootTrackingService {

    private final Client client;
    private final ItemManager itemManager;
    private final MokhaLootTrackerConfig config;
    private final Logger log;
    private final Notifier notifier;
    private final Map<Integer, Integer> previousLootSnapshot;

    private boolean lootWindowWasVisible = false;
    private int lastDetectedWaveInWindow = 0;
    private boolean pendingLootParse = false;
    private int lootWindowItemCountAtLastParse = 0;
    private boolean lootManuallyTakenFromWindow = false;
    private String cachedAlertRulesRaw = null;
    private List<LootAlertRule> cachedAlertRules = Collections.emptyList();

    private static final class LootAlertRule {
        String name;
        String nameKey;
        int minQty;

        LootAlertRule(String name, int minQty) {
            this.name = name;
            this.nameKey = name.toLowerCase();
            this.minQty = minQty;
        }
    }

    static final class LootWindowUpdate {
        private final boolean lootWindowVisible;
        private final int detectedWave;
        private final Map<Integer, Integer> newLootByItemId;
        private final boolean lootManuallyTaken;

        LootWindowUpdate(boolean lootWindowVisible, int detectedWave, Map<Integer, Integer> newLootByItemId,
                boolean lootManuallyTaken) {
            this.lootWindowVisible = lootWindowVisible;
            this.detectedWave = detectedWave;
            this.newLootByItemId = newLootByItemId;
            this.lootManuallyTaken = lootManuallyTaken;
        }

        boolean isLootWindowVisible() {
            return lootWindowVisible;
        }

        int getDetectedWave() {
            return detectedWave;
        }

        Map<Integer, Integer> getNewLootByItemId() {
            return newLootByItemId;
        }

        boolean isLootManuallyTaken() {
            return lootManuallyTaken;
        }
    }

    LootTrackingService(
            Client client,
            ItemManager itemManager,
            MokhaLootTrackerConfig config,
            Logger log,
            Notifier notifier,
            Map<Integer, Integer> previousLootSnapshot) {
        this.client = client;
        this.itemManager = itemManager;
        this.config = config;
        this.log = log;
        this.notifier = notifier;
        this.previousLootSnapshot = previousLootSnapshot;
    }

    LootWindowUpdate pollLootWindow(boolean inMokhaArena) {
        if (!inMokhaArena) {
            lootWindowWasVisible = false;
            lastDetectedWaveInWindow = 0;
            pendingLootParse = false;
            lootWindowItemCountAtLastParse = 0;
            lootManuallyTakenFromWindow = false;
            return new LootWindowUpdate(false, 0, Collections.emptyMap(), false);
        }

        Widget mainWidget = client.getWidget(InterfaceID.DomEndLevelUi.FRAME);
        boolean lootWindowVisible = mainWidget != null && !mainWidget.isHidden();

        int detectedWave = 0;
        Map<Integer, Integer> newLootByItemId = Collections.emptyMap();

        if (lootWindowVisible) {
            int currentWaveInWidget = extractWaveNumber(mainWidget);
            Widget lootContainerWidget = client.getWidget(InterfaceID.DomEndLevelUi.LOOT_CONTENTS);

            boolean risingEdge = !lootWindowWasVisible;
            // Also treat as a new window if the wave number changed — handles the case
            // where the game refreshes the widget in-place between waves without
            // toggling visibility.
            boolean waveChanged = currentWaveInWidget > 0 && currentWaveInWidget != lastDetectedWaveInWindow;
            boolean shouldParse = risingEdge || waveChanged || pendingLootParse;

            if (shouldParse && lootContainerWidget != null) {
                Widget[] children = lootContainerWidget.getChildren();
                if (children != null && children.length > 0) {
                    detectedWave = currentWaveInWidget;
                    lastDetectedWaveInWindow = currentWaveInWidget;
                    newLootByItemId = parseNewLoot(lootContainerWidget);
                    lootWindowItemCountAtLastParse = countVisibleItems(children);
                    pendingLootParse = false;
                } else {
                    // Children not populated yet — retry next tick.
                    if (currentWaveInWidget > 0) {
                        detectedWave = currentWaveInWidget;
                        lastDetectedWaveInWindow = currentWaveInWidget;
                    }
                    pendingLootParse = true;
                }
            } else if (lootWindowVisible && lootWindowWasVisible && lootContainerWidget != null) {
                // Window is still open (no new parse needed). Detect if the player
                // manually removed items from the window (took them to inventory).
                Widget[] children = lootContainerWidget.getChildren();
                if (children != null && lootWindowItemCountAtLastParse > 0) {
                    int currentCount = countVisibleItems(children);
                    if (currentCount < lootWindowItemCountAtLastParse) {
                        lootManuallyTakenFromWindow = true;
                        log.debug("[Mokha] Items removed from loot window ({} → {}), flagging as manually taken",
                                lootWindowItemCountAtLastParse, currentCount);
                    }
                    lootWindowItemCountAtLastParse = currentCount;
                }
            }
        } else {
            // Window just closed — reset per-window state for the next wave.
            lastDetectedWaveInWindow = 0;
            pendingLootParse = false;
            lootWindowItemCountAtLastParse = 0;
        }

        lootWindowWasVisible = lootWindowVisible;
        return new LootWindowUpdate(lootWindowVisible, detectedWave, newLootByItemId, lootManuallyTakenFromWindow);
    }

    private int countVisibleItems(Widget[] children) {
        int count = 0;
        for (Widget child : children) {
            if (child != null && !child.isHidden() && child.getItemQuantity() > 0) {
                count++;
            }
        }
        return count;
    }

    private Map<Integer, Integer> parseNewLoot(Widget containerWidget) {
        Widget[] children = containerWidget.getChildren();
        if (children == null) {
            return Collections.emptyMap();
        }

        Map<Integer, Integer> currentLoot = new HashMap<>();
        Map<String, Integer> currentLootByName = new HashMap<>();
        for (Widget child : children) {
            if (child == null || child.isHidden()) {
                continue;
            }

            int itemId = child.getItemId();
            int itemQuantity = child.getItemQuantity();
            if (itemId <= 0 || itemQuantity <= 0) {
                continue;
            }

            String itemName = itemManager.getItemComposition(itemId).getName();
            if (itemName == null || itemName.isEmpty() || itemName.equalsIgnoreCase("null")) {
                continue;
            }

            currentLoot.put(itemId, itemQuantity);
            String nameKey = itemName.toLowerCase();
            currentLootByName.put(nameKey, currentLootByName.getOrDefault(nameKey, 0) + itemQuantity);
        }

        notifyLootAlerts(currentLootByName);

        Map<Integer, Integer> newLootByItemId = new HashMap<>();
        for (Map.Entry<Integer, Integer> entry : currentLoot.entrySet()) {
            int itemId = entry.getKey();
            int currentQty = entry.getValue();
            int previousQty = previousLootSnapshot.getOrDefault(itemId, 0);
            if (currentQty > previousQty) {
                newLootByItemId.put(itemId, currentQty - previousQty);
            }
        }

        previousLootSnapshot.clear();
        previousLootSnapshot.putAll(currentLoot);
        return newLootByItemId;
    }

    private List<LootAlertRule> getAlertRules() {
        String raw = config.lootAlertLines();
        if (raw == null) {
            raw = "";
        }
        if (!raw.equals(cachedAlertRulesRaw)) {
            cachedAlertRulesRaw = raw;
            cachedAlertRules = parseAlertRules(raw);
        }
        return cachedAlertRules;
    }

    private List<LootAlertRule> parseAlertRules(String raw) {
        List<LootAlertRule> rules = new ArrayList<>();
        if (raw.trim().isEmpty()) {
            return rules;
        }

        String[] lines = raw.split("\\r?\\n");
        for (String line : lines) {
            String trimmed = line.trim();
            if (trimmed.isEmpty() || trimmed.startsWith("#")) {
                continue;
            }

            int commaIndex = trimmed.indexOf(',');
            if (commaIndex < 0) {
                log.warn("[Mokha] Loot alert line missing comma: {}", trimmed);
                continue;
            }

            String name = trimmed.substring(0, commaIndex).trim();
            String qtyText = trimmed.substring(commaIndex + 1).trim();
            if (name.isEmpty() || qtyText.isEmpty()) {
                log.warn("[Mokha] Loot alert line missing name or quantity: {}", trimmed);
                continue;
            }

            int minQty;
            try {
                minQty = Integer.parseInt(qtyText);
            } catch (NumberFormatException e) {
                log.warn("[Mokha] Loot alert quantity is not a number: {}", trimmed);
                continue;
            }

            if (minQty <= 0) {
                log.warn("[Mokha] Loot alert quantity must be positive: {}", trimmed);
                continue;
            }

            rules.add(new LootAlertRule(name, minQty));
        }

        return rules;
    }

    private void notifyLootAlerts(Map<String, Integer> currentLootByName) {
        if (currentLootByName.isEmpty()) {
            return;
        }

        List<LootAlertRule> rules = getAlertRules();
        if (rules.isEmpty()) {
            return;
        }

        for (LootAlertRule rule : rules) {
            Integer qty = currentLootByName.get(rule.nameKey);
            if (qty != null && qty >= rule.minQty) {
                String message = String.format("[Mokha Tracker] Loot alert: %s x%d (>= %d)", rule.name, qty,
                        rule.minQty);
                client.addChatMessage(ChatMessageType.GAMEMESSAGE, "", message, null);
                notifier.notify(message);
            }
        }
    }

    private int extractWaveNumber(Widget mainWidget) {
        if (mainWidget == null) {
            return 0;
        }

        String text = mainWidget.getText();
        if (text != null && text.toLowerCase().contains("wave")) {
            try {
                String[] parts = text.split("\\s+");
                for (int i = 0; i < parts.length - 1; i++) {
                    if (parts[i].equalsIgnoreCase("wave")) {
                        return Integer.parseInt(parts[i + 1].replaceAll("[^0-9]", ""));
                    }
                }
            } catch (NumberFormatException e) {
                // Ignore parsing errors.
            }
        }

        Widget[] children = mainWidget.getChildren();
        if (children != null) {
            for (Widget child : children) {
                if (child == null) {
                    continue;
                }

                String childText = child.getText();
                if (childText == null || !childText.toLowerCase().contains("wave")) {
                    continue;
                }

                try {
                    String[] parts = childText.split("\\s+");
                    for (int i = 0; i < parts.length - 1; i++) {
                        if (parts[i].equalsIgnoreCase("wave")) {
                            return Integer.parseInt(parts[i + 1].replaceAll("[^0-9]", ""));
                        }
                    }
                } catch (NumberFormatException e) {
                    // Ignore parsing errors.
                }
            }
        }

        return 0;
    }
}

