            new int[] { 23987, 23989, 24125 },
            "crystal_halberd",
            ConfigFormat.INTEGER,
            "crystal halberd",
            new ChargeIngredient[] {
                    new ChargeIngredient(ChargeIngredient.CRYSTAL_SHARD, 1, 100, true)
            }),

    // Includes cyan and red recolor variants (charged + uncharged each).
    SERPENTINE_HELM("Serpentine Helm",
            new int[] { 12931, 12929, 13197, 13196, 13199, 13198 },
            "serpentine_helm",
            ConfigFormat.INTEGER,
            "serpentine",
            new ChargeIngredient[] {
                    new ChargeIngredient(ChargeIngredient.ZULRAH_SCALE, 1)
            });

    // ─────────────────────────────────────────────────────────────────────────────

    enum ConfigFormat {
        BLOWPIPE_JSON, INTEGER
    }

    /**
     * One ingredient in a per-charge recipe.
     * Cost per charge = (numerator / denominator) × GE price of itemId.
     * priceless items are counted in tooltips but contribute 0 GP to cost.
     */
    static final class ChargeIngredient {
        // Item IDs referenced in charge recipes (from RuneLite gameval constants).
        // Declared here so they're co-located with the recipes that use them.
        static final int FIRE_RUNE = 554; // ItemID.FIRUNE
        static final int DEATH_RUNE = 560; // ItemID.DEATHRUNE
        static final int CHAOS_RUNE = 562; // ItemID.CHAOSRUNE
        static final int BLOOD_RUNE = 565; // ItemID.BLOODRUNE
        static final int SOUL_RUNE = 566; // ItemID.SOULRUNE
        static final int ZULRAH_SCALE = 12934; // ItemID.SNAKEBOSS_SCALE
        static final int VIAL_OF_BLOOD = 22446; // ItemID.VIAL_BLOOD
        static final int CRYSTAL_SHARD = 23962; // ItemID.PRIF_CRYSTAL_SHARD
        static final int ANCIENT_ESSENCE = 27616; // ItemID.ANCIENT_ESSENCE
        static final int DEMON_TEAR = 31111; // ItemID.DEMON_TEAR

        final int itemId;
        final int numerator; // items consumed per `denominator` charges
        final int denominator; // charge batch size (1 = per charge, 100 = per 100 charges)
        final boolean priceless;

        ChargeIngredient(int itemId, int numerator) {
            this(itemId, numerator, 1, false);
        }

        ChargeIngredient(int itemId, int numerator, int denominator) {
            this(itemId, numerator, denominator, false);
        }

        ChargeIngredient(int itemId, int numerator, int denominator, boolean priceless) {
            this.itemId = itemId;
            this.numerator = numerator;
            this.denominator = denominator;
            this.priceless = priceless;
        }

        /** Total quantity of this ingredient for {@code charges} charges consumed. */
        double totalQuantity(int charges) {
            return (double) charges * numerator / denominator;
        }
    }

    final String displayName;
    final int[] itemIds;
    final String tictacConfigKey;
    final ConfigFormat configFormat;
    /**
     * Lowercase substring expected in a "check charges" chat message for this
     * weapon.
     */
    final String chatKeyword;
    /**
     * Charge recipe for cost calculation. Null for BLOWPIPE_JSON weapons (items
     * tracked
     * directly from the JSON storage delta). Empty array means recipe is unknown.
     */
    final ChargeIngredient[] chargeRecipe;

    TrackedWeapon(String displayName, int[] itemIds, String tictacConfigKey,
            ConfigFormat configFormat, String chatKeyword, ChargeIngredient[] chargeRecipe) {
        this.displayName = displayName;
        this.itemIds = itemIds;
        this.tictacConfigKey = tictacConfigKey;
        this.configFormat = configFormat;
        this.chatKeyword = chatKeyword;
        this.chargeRecipe = chargeRecipe;
    }

    /** Returns the TrackedWeapon whose tictac7x config key matches, or null. */
    static TrackedWeapon fromConfigKey(String key) {
        if (key == null)
            return null;
        for (TrackedWeapon w : values()) {
            if (w.tictacConfigKey.equals(key))
                return w;
        }
        return null;
    }

    /**
     * Returns the INTEGER-format TrackedWeapon whose canonical item ID matches, or
     * null.
     */
    static TrackedWeapon fromCanonicalItemId(int itemId) {
        if (itemId <= 0)
            return null;
        for (TrackedWeapon w : values()) {
            if (w.configFormat == ConfigFormat.INTEGER && w.itemIds[0] == itemId)
                return w;
        }
        return null;
    }

    /**
     * Returns true if itemId matches any item ID declared for an INTEGER-format
     * weapon.
     * Used to decide whether to apply 0 GP cost when committing charge consumption.
     */
    static boolean isConfigChargeItemId(int itemId) {
        if (itemId <= 0)
            return false;
        for (TrackedWeapon w : values()) {
            if (w.configFormat != ConfigFormat.INTEGER)
                continue;
            for (int id : w.itemIds) {
                if (id == itemId)
                    return true;
            }
        }
        return false;
    }
}

package com.camjewell;

import java.util.List;
import java.util.Map;

class ValueCalculationService {
    private static final int ULTRA_VALUABLE_THRESHOLD = 20_000_000;

    long calculateUnadjustedCurrentRunLootValue(Map<Integer, List<LootItem>> lootByWave) {
        long total = 0;
        for (List<LootItem> items : lootByWave.values()) {
            for (LootItem item : items) {
                total += item.value;
            }
        }
        return total;
    }

    long calculateCurrentRunLootValue(
            Map<Integer, List<LootItem>> lootByWave,
            MokhaLootTrackerConfig config) {
        long currentRunValue = 0;
        for (List<LootItem> items : lootByWave.values()) {
            for (LootItem item : items) {
                currentRunValue += getAdjustedLootItemValue(item.name, item.value, config);
            }
        }
        return currentRunValue;
    }

    long calculateCurrentRunLootHaValue(
            Map<Integer, List<LootItem>> lootByWave,
            MokhaLootTrackerConfig config) {
        long currentRunValue = 0;
        for (List<LootItem> items : lootByWave.values()) {
            for (LootItem item : items) {
                currentRunValue += getAdjustedLootItemValue(item.name, item.haValue, config);
            }
        }
        return currentRunValue;
    }

    long getAdjustedLootItemValue(String itemName, long trackedValue, MokhaLootTrackerConfig config) {
        return shouldIgnoreLootItem(itemName, config) ? 0 : trackedValue;
    }

    boolean shouldIgnoreLootItem(String itemName, MokhaLootTrackerConfig config) {
        return config.ignoreSpiritSeedsValue() && itemName.equals("Spirit seed");
    }

    void applyIgnoreSettingsToHistoricalItems(
            Map<Integer, Map<String, ItemAggregate>> historicalItems,
            MokhaLootTrackerConfig config) {
        for (Map<String, ItemAggregate> waveItems : historicalItems.values()) {
            for (ItemAggregate item : waveItems.values()) {
                if (item.name.equals("Spirit seed")) {
                    item.totalValue = config.ignoreSpiritSeedsValue() ? 0 : 140000L * item.totalQuantity;
                }
            }
        }
    }

    long recalculateHistoricalTotalClaimed(
            Map<Integer, Map<String, ItemAggregate>> historicalClaimedItemsByWave,
            MokhaLootTrackerConfig config) {
        long total = 0;
        boolean excludeUltra = config.excludeUltraValuableItems();

        for (Map<String, ItemAggregate> waveItems : historicalClaimedItemsByWave.values()) {
            for (ItemAggregate item : waveItems.values()) {
                if (excludeUltra && item.pricePerItem > ULTRA_VALUABLE_THRESHOLD) {
                    continue;
                }
                total += item.totalValue;
            }
        }

        return total;
    }

    long calculateTotalUnclaimed(
            Map<Integer, Map<String, ItemAggregate>> historicalUnclaimedItemsByWave,
            Map<Integer, Long> historicalUnclaimedByWave,
            MokhaLootTrackerConfig config) {
        long totalUnclaimed = 0;

        if (config.excludeUltraValuableItems()) {
            for (Map<String, ItemAggregate> waveItems : historicalUnclaimedItemsByWave
                    .values()) {
                for (ItemAggregate item : waveItems.values()) {
                    if (item.pricePerItem <= ULTRA_VALUABLE_THRESHOLD) {
                        totalUnclaimed += item.totalValue;
                    }
                }
            }
        } else {
            for (Long waveValue : historicalUnclaimedByWave.values()) {
                totalUnclaimed += waveValue;
            }
        }

        return totalUnclaimed;
    }

    void recalculateWaveTotals(
            Map<Integer, Map<String, ItemAggregate>> historicalClaimedItemsByWave,
            Map<Integer, Map<String, ItemAggregate>> historicalUnclaimedItemsByWave,
            Map<Integer, Long> historicalClaimedByWave,
            Map<Integer, Long> historicalUnclaimedByWave,
            MokhaLootTrackerConfig config) {
        boolean excludeUltra = config.excludeUltraValuableItems();

        historicalClaimedByWave.clear();
        for (Map.Entry<Integer, Map<String, ItemAggregate>> waveEntry : historicalClaimedItemsByWave
                .entrySet()) {
            long waveTotal = 0;
            for (ItemAggregate item : waveEntry.getValue().values()) {
                if (excludeUltra && item.pricePerItem > ULTRA_VALUABLE_THRESHOLD) {
                    continue;
                }
                waveTotal += item.totalValue;
            }
            historicalClaimedByWave.put(waveEntry.getKey(), waveTotal);
        }

        historicalUnclaimedByWave.clear();
        for (Map.Entry<Integer, Map<String, ItemAggregate>> waveEntry : historicalUnclaimedItemsByWave
                .entrySet()) {
            long waveTotal = 0;
            for (ItemAggregate item : waveEntry.getValue().values()) {
                if (excludeUltra && item.pricePerItem > ULTRA_VALUABLE_THRESHOLD) {
                    continue;
                }
                waveTotal += item.totalValue;
            }
            historicalUnclaimedByWave.put(waveEntry.getKey(), waveTotal);
        }
    }

}

package com.camjewell;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.util.Collections;
import java.util.List;
import java.util.Set;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.PanelComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

class WeaponChecklistOverlay extends Overlay {
    enum Phase {
        INITIAL, FINAL
    }

    private final PanelComponent panelComponent = new PanelComponent();
    private Phase phase;
    private List<TrackedWeapon> weapons = Collections.emptyList();
    private Set<TrackedWeapon> checked = Collections.emptySet();

    WeaponChecklistOverlay() {
        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    void showInitial(List<TrackedWeapon> weapons, Set<TrackedWeapon> checked) {
        this.phase = Phase.INITIAL;
        this.weapons = weapons;
        this.checked = checked;
    }

    void showFinal(List<TrackedWeapon> weapons, Set<TrackedWeapon> checked) {
        this.phase = Phase.FINAL;
        this.weapons = weapons;
        this.checked = checked;
    }

    void update(List<TrackedWeapon> weapons, Set<TrackedWeapon> checked) {
        this.weapons = weapons;
        this.checked = checked;
    }

    void hide() {
        phase = null;
    }

    @Override
    public Dimension render(Graphics2D graphics) {
        if (phase == null || weapons.isEmpty()) {
            return null;
        }

        panelComponent.getChildren().clear();
        panelComponent.getChildren().add(TitleComponent.builder()
                .text("Doom Loot Tracker")
                .color(Color.YELLOW)
                .build());

        String subtitle = phase == Phase.INITIAL
                ? "Check charges to begin tracking:"
                : "Check charges to record usage:";
        panelComponent.getChildren().add(LineComponent.builder()
                .left(subtitle)
                .leftColor(Color.WHITE)
                .build());

        for (TrackedWeapon weapon : weapons) {
            boolean isDone = checked.contains(weapon);
            panelComponent.getChildren().add(LineComponent.builder()
                    .left((isDone ? "[+] " : "[ ] ") + weapon.displayName)
                    .leftColor(isDone ? Color.GREEN : Color.LIGHT_GRAY)
                    .build());
        }

        return panelComponent.render(graphics);
    }
}

